<div class="page-heading"><div><h1><?= e(t('Review calendar import')) ?></h1><p><?= e(t('Only these events will be added or updated. Existing imported UIDs update their linked appointment.')) ?></p></div></div><section class="card"><div class="table-wrap"><table><thead><tr><th><?= e(t('Title')) ?></th><th><?= e(t('Starts')) ?></th><th><?= e(t('Ends')) ?></th><th><?= e(t('Status')) ?></th></tr></thead><tbody><?php foreach ($events as $row): ?><tr><td><?= e($row['title']) ?></td><td><?= e(!empty($row['all_day']) ? t('All day').' '.substr($row['starts_at'],0,10) : $row['starts_at']) ?></td><td><?= e(!empty($row['all_day']) ? (new DateTimeImmutable($row['ends_at']))->modify('-1 day')->format('Y-m-d') : $row['ends_at']) ?></td><td><?= e($row['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><form method="post" action="/connectivity/calendar/import"><?= csrf_field() ?><button><?= e(t('Confirm')) ?> <?= count($events) ?> <?= e(t('events')) ?></button><a href="/connectivity"><?= e(t('Cancel')) ?></a></form></section>
